use serde::Serialize;
use std::time::Instant;
use crate::{scene::Scene,gpu::Gpu,log::Log,hud_stream::HudCost};
pub const N:usize=20;
pub const NAMES:[&str;N]=["자료준비","유닛계산","투사체계산및업로드","사망이력","인스턴스업로드","Scene전체","HUD동기그리기","HUD동기팩","HUD전송","HUDmip제출","HUD렌더스레드전체","drawResolve제출","swapchain대기","endFrame","입력","HUD준비스레드그리기","HUD준비스레드팩","HUD준비스레드차이","예약","CPU전체"];
pub fn ms(start:Instant)->f64{start.elapsed().as_secs_f64()*1000.0}
#[derive(Default,Clone,Copy)]pub struct Frame{pub values:[f64;N],pub hud_updated:bool,pub hud_bytes:u64}
impl Frame{pub fn scene(&mut self,s:&Scene){self.values[..6].copy_from_slice(&s.phase);}pub fn hud(&mut self,c:HudCost){for(i,v)in[(6,c.render),(7,c.pack),(8,c.transfer),(9,c.mip),(10,c.total),(15,c.worker_render),(16,c.worker_pack),(17,c.worker_diff)]{self.values[i]=v;}self.hud_updated=c.updated;self.hud_bytes=c.bytes;}}
#[derive(Serialize)]pub struct Summary{pub mean:f64,pub p50:f64,pub p95:f64,pub p99:f64,pub max:f64}
fn summarize(mut v:Vec<f64>)->Summary{if v.is_empty(){return Summary{mean:0.0,p50:0.0,p95:0.0,p99:0.0,max:0.0};}let mean=v.iter().sum::<f64>()/v.len()as f64;v.sort_by(f64::total_cmp);let p=|n:usize|v[(v.len()*n/100).min(v.len()-1)];Summary{mean,p50:p(50),p95:p(95),p99:p(99),max:*v.last().unwrap()}}
pub struct Profile{frames:Vec<Frame>,pub reports:Vec<serde_json::Value>,output:Option<(std::path::PathBuf,Log)>}
impl Profile{pub fn new()->Self{Self{frames:Vec::with_capacity(1600),reports:Vec::with_capacity(256),output:None}}pub fn runtime(log:&Log)->Self{let mut p=Self::new();let time=std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_millis();p.output=Some((crate::log::root().join(format!("_tmp/logs/native_runtime_profile_{}_{time}.json",std::process::id())),log.clone()));p}pub fn frame(&mut self,f:Frame){if self.frames.len()<1600{self.frames.push(f);}}
 pub fn report(&mut self,log:&Log,scene:&Scene,gpu:&Gpu,elapsed:f64){let stats:Vec<_>=(0..N).map(|i|serde_json::json!({"구간":NAMES[i],"ms":summarize(self.frames.iter().map(|f|f.values[i]).collect())})).collect();let hud:Vec<_>=self.frames.iter().filter(|f|f.hud_updated).map(|f|f.values[19]).collect();let other:Vec<_>=self.frames.iter().filter(|f|!f.hud_updated).map(|f|f.values[19]).collect();let bytes:u64=self.frames.iter().map(|f|f.hud_bytes).sum();log.line(format!("구간계측 Scene평균={:.3} HUD메인평균={:.3}ms HUD갱신프레임={} bytes={} atlasUploads={} 목록={}",self.frames.iter().map(|f|f.values[5]).sum::<f64>()/self.frames.len().max(1)as f64,self.frames.iter().map(|f|f.values[10]).sum::<f64>()/self.frames.len().max(1)as f64,hud.len(),bytes,gpu.atlas_uploads.get(),scene.runtime_sizes()));if self.reports.len()<256{self.reports.push(serde_json::json!({"elapsed":elapsed,"frames":self.frames.len(),"phases":stats,"HUD갱신CPU":summarize(hud),"HUD없음CPU":summarize(other),"HUD전송바이트":bytes,"atlasUploads":gpu.atlas_uploads.get(),"batchSorts":gpu.batch_sorts.get(),"hudUploads":gpu.hud_uploads.get(),"sizes":scene.runtime_sizes()}));}self.frames.clear();}
}
impl Drop for Profile{fn drop(&mut self){if let Some((path,log))=&self.output{match serde_json::to_vec_pretty(&self.reports).and_then(|bytes|std::fs::write(path,bytes).map_err(serde_json::Error::io)){Ok(())=>log.line(format!("세션 구간 계측 저장={}",path.display())),Err(e)=>log.line(format!("세션 계측 저장 실패={e}"))}}}}
